{
  "name": "opencode-move-tool",
  "version": "1.1.0",
  "description": "Single-operation code relocation tool for OpenCode agents — move code between files without copy-then-delete",
  "type": "module",
  "main": "dist/move.js",
  "exports": {
    ".": "./dist/move.js"
  },
  "scripts": {
    "build": "bun build ./move.ts --target=node --format=esm --external @opencode-ai/plugin --outfile ./dist/move.js",
    "prepare": "bun run build",
    "postinstall": "node install.mjs",
    "test": "tsx --test test/*.test.ts",
    "typecheck": "tsc --noEmit"
  },
  "files": [
    "dist/move.js",
    "move-core.ts",
    "install.mjs",
    "SKILL.md",
    "README.md"
  ],
  "repository": {
    "type": "git",
    "url": "git+https://github.com/FRFlo/opencode-move-tool.git"
  },
  "bugs": {
    "url": "https://github.com/FRFlo/opencode-move-tool/issues"
  },
  "homepage": "https://github.com/FRFlo/opencode-move-tool#readme",
  "keywords": [
    "opencode",
    "tool",
    "move",
    "refactoring",
    "code-relocation",
    "opencode-plugin"
  ],
  "license": "MIT",
  "engines": {
    "node": ">=20"
  },
  "dependencies": {
    "@opencode-ai/plugin": "^1.4.6"
  },
  "devDependencies": {
    "@types/node": "^25.9.1",
    "tsx": "^4.19.0",
    "typescript": "^5.4.0"
  }
}
